def sort_even(l: list):
    evens = sorted([l[i] for i in range(0, len(l), 2)])
    result = l.copy()
    for i in range(0, len(l), 2):
        result[i] = evens[i // 2]
    return result

def sort_even(l: list):
    evens = sorted([l[i] for i in range(0, len(l), 2)])
    result = l.copy()
    for i, val in zip(range(0, len(l), 2), evens):
        result[i] = val
    return result

def sort_even(l: list):
    evens = sorted(l[::2])
    result = l.copy()
    for i, val in enumerate(evens):
        result[2 * i] = val
    return result

def sort_even(l: list):
    evens = sorted(l[::2])
    result = l[:]
    for i, val in zip(range(0, len(l), 2), evens):
        result[i] = val
    return result

