    n = len(l)
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            total = l[i] + l[left] + l[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False

